CREATE OR REPLACE FUNCTION public.export_voice_data_to_drive() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$ DECLARE headers jsonb; bearer text; BEGIN IF TG_TABLE_NAME='voice_session_feedbacks' THEN IF NEW.duration_seconds IS NULL OR NULLIF(trim(NEW.transcript),'') IS NULL THEN RETURN NEW; END IF; IF TG_OP='UPDATE' AND NEW.transcript IS NOT DISTINCT FROM OLD.transcript AND NEW.duration_seconds IS NOT DISTINCT FROM OLD.duration_seconds AND NEW.elevenlabs_conversation_id IS NOT DISTINCT FROM OLD.elevenlabs_conversation_id THEN RETURN NEW; END IF; END IF; headers := COALESCE(NULLIF(current_setting('request.headers', true),''),'{}')::jsonb; bearer := headers->>'authorization'; IF NULLIF(bearer,'') IS NULL THEN RAISE WARNING 'Voice Drive webhook needs an authenticated API request'; RETURN NEW; END IF; PERFORM net.http_post(url:='https://wjjugtdciljmuohxoqcj.supabase.co/functions/v1/export-to-drive',headers:=jsonb_build_object('Content-Type','application/json','Authorization',bearer),body:=jsonb_build_object('action','export_voice','user_id',NEW.user_id),timeout_milliseconds:=120000); RETURN NEW; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Voice Drive webhook failed: %',SQLERRM; RETURN NEW; END; $$; REVOKE ALL ON FUNCTION public.export_voice_data_to_drive() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.export_voice_data_to_drive() TO service_role; CREATE TRIGGER daily_voice_prompts_drive AFTER INSERT OR UPDATE OF prompts ON public.daily_voice_prompts FOR EACH ROW EXECUTE FUNCTION public.export_voice_data_to_drive(); CREATE TRIGGER voice_session_feedbacks_drive AFTER INSERT OR UPDATE OF transcript,duration_seconds,elevenlabs_conversation_id ON public.voice_session_feedbacks FOR EACH ROW EXECUTE FUNCTION public.export_voice_data_to_drive();